// Parse review notification data
try {
  const input = $input.item.json;

  // Extract fields from input
  const platform_name = input.platform_name || input.platform || '';
  const guest_name = input.guest_name || input.guestName || input.name || '';
  const property_name = input.property_name || input.propertyName || input.property || '';
  const star_rating = input.star_rating || input.rating || input.stars || 0;
  const review_text = input.review_text || input.reviewText || input.review || input.text || '';

  // Generate unique review_id using timestamp and random string
  const timestamp = Date.now();
  const randomString = Math.random().toString(36).substring(2, 8);
  const review_id = `review_${timestamp}_${randomString}`;

  // Check if we have minimum required data
  const parse_success = !!(platform_name && guest_name && review_text);

  // Return all extracted fields
  return {
    review_id,
    platform_name,
    guest_name,
    property_name,
    star_rating,
    review_text,
    parse_success,
    parsed_at: new Date().toISOString()
  };

} catch (error) {
  // If parsing fails, return error state
  return {
    review_id: '',
    platform_name: '',
    guest_name: '',
    property_name: '',
    star_rating: 0,
    review_text: '',
    parse_success: false,
    error_message: error.message
  };
}

