// Extract AI response from OpenAI API
const openAIResponse = $input.item.json;

// Parse the AI response JSON
let aiAnalysis;
try {
  // OpenAI returns the response in choices[0].message.content
  const content = openAIResponse.choices[0].message.content;
  aiAnalysis = JSON.parse(content);
} catch (error) {
  throw new Error('Failed to parse AI response: ' + error.message);
}

// Extract fields from AI analysis
const sentiment = aiAnalysis.sentiment;
const topics = aiAnalysis.topics;
const response_text = aiAnalysis.response_text;
const confidence = aiAnalysis.confidence;

// Get star rating from previous node data
const star_rating = $('Parse Review Data').item.json.star_rating;

// Determine if approval is required
// Approval needed if: confidence < 85 OR star_rating < 4 OR sentiment is 'negative'
const approval_required = confidence < 85 || star_rating < 4 || sentiment === 'negative';

// Determine approval urgency
let approval_urgency = 'normal';
if (sentiment === 'negative' && star_rating < 4) {
  approval_urgency = 'high';
}

// Return all fields including AI analysis
return {
  sentiment: sentiment,
  topics: topics,
  response_text: response_text,
  confidence: confidence,
  star_rating: star_rating,
  approval_required: approval_required,
  approval_urgency: approval_urgency,
  // Include original data from previous nodes
  ...openAIResponse,
  ai_analysis: aiAnalysis
};

// Get data from previous nodes
const reviewData = $input.item.json;
const propertyConfig = $('Get Property Configuration').item.json;
const aiAnalysis = $('OpenAI Analyze Review').item.json;
const approvalData = $('Determine Approval Requirement').item.json;

// Extract review details
const platformName = reviewData.platform || 'Unknown Platform';
