const guestName = reviewData.guestName || 'Guest';

// Create star emoji string
const starEmoji = '⭐'.repeat(Math.floor(starRating));

// Extract AI analysis data
const sentiment = aiAnalysis.sentiment || 'neutral';
const topics = aiAnalysis.topics || [];
const aiResponse = aiAnalysis.generatedResponse || 'No response generated';

// Format topics as a comma-separated list
const topicsText = topics.length > 0 ? topics.join(', ') : 'None identified';

// Check if review needs urgent attention (under 4 stars)
const isUrgent = starRating < 4;
const urgencyFlag = isUrgent ? '🚩 ' : '';
const urgencyNote = isUrgent ? '

🚩 URGENT: This review is below 4 stars and requires immediate attention!' : '';

// Format the message
const formattedMessage = `${urgencyFlag}**New Review Received**

**Platform:** ${platformName}
**Property:** ${propertyName}
**Guest:** ${guestName}
**Rating:** ${starEmoji} (${starRating}/5)

**Review:**
${reviewText}

---

**AI Analysis:**
• **Sentiment:** ${sentiment}
• **Topics:** ${topicsText}

**AI-Generated Response Draft:**
${aiResponse}${urgencyNote}

---

Please choose an action below:`;

